 const extraStyle=document.createElement('style');extraStyle.textContent=`#pbResolve.pb-ready .track i{box-shadow:0 0 15px #ffd98acc,0 0 28px #8cf8dc66;background:linear-gradient(90deg,#78e9d9,#fff0b2)}#pbResolve.pb-ready label{color:#ffe4a4}#pbCineBars{position:fixed;inset:0;pointer-events:none;z-index:35;opacity:0;transition:opacity .18s}#pbCineBars.show{opacity:1}#pbCineBars:before,#pbCineBars:after{content:'';position:absolute;left:0;right:0;height:9vh;background:#020507e8;transition:transform .22s}#pbCineBars:before{top:0;transform:translateY(-100%)}#pbCineBars:after{bottom:0;transform:translateY(100%)}#pbCineBars.show:before,#pbCineBars.show:after{transform:none}#pbCineCaption{position:absolute;left:0;right:0;top:50%;transform:translateY(-50%);text-align:center;text-shadow:0 4px 20px #000;letter-spacing:5px;color:#f9e2ac;font-size:10px;opacity:0;transition:opacity .18s}#pbCineBars.show #pbCineCaption{opacity:.9}#pbCineCaption b{display:block;color:#fff7dc;font-size:22px;letter-spacing:8px;margin-top:5px}#pbResolveBurst{position:fixed;inset:0;pointer-events:none;z-index:34;opacity:0;background:radial-gradient(circle at 50% 54%,#fff6ca99 0,#74f7df44 14%,transparent 37%);mix-blend-mode:screen}#pbResolveBurst.show{animation:pbResolveFlash .38s ease-out}@keyframes pbResolveFlash{0%{opacity:0}18%{opacity:1}100%{opacity:0}}@media(max-height:500px){#pbCineBars:before,#pbCineBars:after{height:7vh}#pbCineCaption b{font-size:18px}}`;document.head.appendChild(extraStyle);
 const cine=document.createElement('div');cine.id='pbCineBars';cine.innerHTML='<div id="pbCineCaption"><span>PHASE TRANSITION</span><b></b></div>';document.body.appendChild(cine);const resolveBurst=document.createElement('div');resolveBurst.id='pbResolveBurst';document.body.appendChild(resolveBurst);
