 const v2ResolveSwing=resolveSwing;resolveSwing=function(){const hp=boss?.hp||0,swing=player.swing?{...player.swing}:null,out=v2ResolveSwing();if(boss&&boss.hp<hp)addResolve(swing?.counter?13:swing?.combo===2?8:4);return out};
 function fireResolve(){if(state.resolve<100||state.ultimateT>0||state.cineT>0||mode!=='play'||!boss||boss.hp<=0||player.hp<=0)return false;state.resolve=0;state.ultimateT=.72;state.ultimateHit=false;state.resolveFlash=.42;updateResolveUI();player.invuln=Math.max(player.invuln,.82);player.stun=0;player.cool=0;player.swing=null;player.attack=.62;player.motion=1;player.motionDuration=.62;player.motionContact=.27;const to=norm(sub(boss.pos,player.pos));player.face=Math.atan2(to.x,to.z);player.vel=mul(to,11.5);boss.stun=Math.max(boss.stun,.38);boss.wind=0;boss.strike=0;boss.pattern=null;announce('月 影 断 ち',.8);sound(510,.16,'triangle',.055);feel.slow=Math.max(feel.slow,.18);feel.flash=Math.max(feel.flash,.08);resolveBurst.classList.remove('show');void resolveBurst.offsetWidth;resolveBurst.classList.add('show');return true}
 function resolveContact(){if(state.ultimateHit||!boss||boss.hp<=0)return;state.ultimateHit=true;const to=norm(sub(boss.pos,player.pos)),point=bossPoint(),force=add(mul(to,44),V(0,14,0)),damage=level===4?38:34;hurt(boss,damage,force,point);boss.posture=Math.min(115,boss.posture+34);boss.stun=Math.max(boss.stun,1.15);ring(point,'#fff0b2');ring(V(boss.pos.x,.05,boss.pos.z),'#7fffe6');burst(point,'#fff3bd',32,10);burst(point,'#75f6de',22,8);impact(point,'finish',2.15);shake=Math.max(shake,.48);hitstop=Math.max(hitstop,.14);feel.slow=Math.max(feel.slow,.32);feel.flash=Math.max(feel.flash,.16);sound(78,.42,'sawtooth',.09)}
 const attackBtn=$('attack'),oldAttackDown=attackBtn.onpointerdown;let holdTimer=0,holdPointer=null,holdFired=false;attackBtn.onpointerdown=e=>{if(state.resolve<100||state.cineT>0||state.ultimateT>0)return oldAttackDown?.call(attackBtn,e);e.preventDefault();holdPointer=e.pointerId;holdFired=false;attackBtn.setPointerCapture?.(e.pointerId);attackBtn.classList.add('pressed');clearTimeout(holdTimer);holdTimer=setTimeout(()=>{if(holdPointer===e.pointerId){holdFired=fireResolve()}},380)};const releaseHold=e=>{if(holdPointer===null||e.pointerId!==holdPointer)return;clearTimeout(holdTimer);if(!holdFired&&state.resolve>=100&&state.cineT<=0)attackQueued=true;holdPointer=null;holdFired=false;attackBtn.classList.remove('pressed')};attackBtn.addEventListener('pointerup',releaseHold);attackBtn.addEventListener('pointercancel',releaseHold);attackBtn.addEventListener('lostpointercapture',releaseHold);addEventListener('keydown',e=>{if(e.code==='KeyJ'&&e.shiftKey&&state.resolve>=100){e.preventDefault();e.stopImmediatePropagation();fireResolve()}},true);
 const v2StartAttack=startEnemyAttack;startEnemyAttack=function(move){if(level!==4)return v2StartAttack(move);const total=Math.max(1,state.parryAttempts),parryRate=parries/total,activity=state.attacks/Math.max(1,state.attacks+state.parryAttempts),retreatRate=state.retreat/Math.max(1,state.retreat+state.advance);let pick=move,profile='BALANCED';if(parryRate>.58){pick=ENEMY_MOVES[4][3];profile='DELAY BREAKER'}else if(retreatRate>.58){pick=ENEMY_MOVES[4][1];profile='PURSUIT'}else if(activity>.62){pick=ENEMY_MOVES[4][2];profile='COUNTER STEP'}else if((boss.sequence||0)%3===0){pick=ENEMY_MOVES[4][0];profile='MIRROR CHAIN'}state.secretProfile=profile;pick={...pick,hits:[...(pick.hits||[])]};if(profile==='DELAY BREAKER')pick.wind*=1.22;else if(profile==='PURSUIT')pick.speed*=1.16;else if(profile==='COUNTER STEP')pick.wind*=.92;return v2StartAttack(pick)};
 const v2Reset=reset;reset=function(l=0){const out=v2Reset(l);if(l===0){resetResolve();state.parryAttempts=0;state.attacks=0;state.retreat=state.advance=0}state.lastParries=parries;state.lastPerfects=perfects;state.lastLevel=level;state.lastPhase=diag()?.phase||1;state.ultimateT=0;state.ultimateHit=false;finishCinema();return out};
 const v2Step=step;step=function(dt){const prevPhase=diag()?.phase||state.lastPhase,prevLevel=level;v2Step(dt);const d=diag(),nextPhase=d?.phase||1;if(level!==prevLevel){state.lastLevel=level;state.lastPhase=nextPhase;if(level===4)beginCinema(2.7,'傀 儡 零 式','SECRET DUEL')}else if(nextPhase>prevPhase){state.lastPhase=nextPhase;beginCinema(nextPhase===3?2.55:2.15,d?.phaseName||`PHASE ${nextPhase}`,nextPhase===3?'FINAL PHASE':'PHASE BREAK')}if(mode==='play'&&boss?.hp>0&&player?.hp>0){const to=norm(sub(boss.pos,player.pos)),toward=player.vel.x*to.x+player.vel.z*to.z;if(toward<-.8)state.retreat+=dt;else if(toward>.8)state.advance+=dt}if(state.cineT>0){state.cineT=Math.max(0,state.cineT-dt);player.vel=V();boss.vel=V();player.stun=Math.max(player.stun,state.cineT+.08);boss.stun=Math.max(boss.stun,state.cineT+.1);boss.wind=0;boss.strike=0;attackQueued=parryQueued=false;attackBuffer=parryBuffer=0;if(state.cineT<=0)finishCinema()}if(state.ultimateT>0){state.ultimateT=Math.max(0,state.ultimateT-dt);const to=norm(sub(boss.pos,player.pos));player.face=Math.atan2(to.x,to.z);if(!state.ultimateHit){player.vel=mul(to,12);if(state.ultimateT<=.45||len(sub(boss.pos,player.pos))<2.45)resolveContact()}else player.vel=mul(player.vel,.55)}state.resolveFlash=Math.max(0,state.resolveFlash-dt);state.lastParries=parries;state.lastPerfects=perfects;updateResolveUI()};
 updateResolveUI();window.parryPhaseBreakV2Diagnostics=()=>({resolve:+state.resolve.toFixed(1),cine:+state.cineT.toFixed(2),ultimate:+state.ultimateT.toFixed(2),profile:state.secretProfile,parryAttempts:state.parryAttempts,attacks:state.attacks,retreat:+state.retreat.toFixed(2),advance:+state.advance.toFixed(2)});
